(()=>{'use strict';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function main(){const resp=await fetch('/o-iokl-minimal-demo-20261027.json',{cache:'no-store'});if(!resp.ok)throw Error('HTTP '+resp.status);const d=await resp.json();if(d.schema!=='minimal-iokl-key-demo-20261027-v1')throw Error('资料版本不匹配');
const h=document.querySelector('#main');h.innerHTML=`<section><h2>先把实际与模拟分开</h2><div class="initial-source"><img src="${d.image}" alt="ộ锁定原字形"><div><p><strong>现行可用：</strong><code>iots / otsi</code> 选圆下点；<code>ioyw / oywi</code> 选圆上折线。</p><p><strong>本页模拟：</strong><code>iokl / okli</code> 一次表达“主体外恰2件，一折线一点”；当前服务人数仍0。</p></div></div><div class="notice warning"><strong>真正新增的代价：</strong><code>iok</code>并未固定外二件组。只有补上末位<code>l</code>，才按候选的<code>k/l</code>分支选择该组；这里的l不再是原来的“左上斜”。其它C/l旧义保留，旧k全字组也保留。必须额外批准这项条件换义，不能由8孔组方向的接受自动推出同意。</div></section><section><h2>1. 逐键看对象怎样确定</h2><p>先选一条路径，再按“下一键”或在输入框逐键输入。下面只是当前快照的分步说明；候选码不会发给实际查询服务。</p><div class="selectors"><label>对照路径<select id="route">${d.paths.map((p,i)=>`<option value="${i}" ${p.kind==='candidate'?'selected':''}>${p.kind==='candidate'?'模拟候选':'现行入口'} ${p.canonical} · ${esc(p.title)}</option>`).join('')}</select></label><label>查询顺序<select id="order"><option value="front">前置ABCD</option><option value="back">后置BCDA</option></select></label></div><div class="work"><div><div class="figure"><img src="${d.image}" alt="ộ的同一锁定原图"><svg id="object-boxes" viewBox="0 0 64 64" aria-hidden="true"></svg></div><p id="object-scope" class="scope"></p></div><div><span id="mode-label" class="tag"></span><div class="keycaps" id="keycaps"></div><div class="controls"><label style="margin:0">本条键串 <input id="typed" type="text" inputmode="text" maxlength="4" autocomplete="off" spellcheck="false" aria-label="本页分步键串" style="width:130px"></label><button id="next-key">下一键</button><button id="previous-key">退一键</button><button id="reset">重看</button></div><p id="input-status" class="status" role="status"></p><div id="step-box" class="step-box" role="status"></div><div class="number-grid"><div class="number"><small>这个前缀的现行快照人数</small><strong id="current-count">—</strong><span id="current-target" class="muted"></span></div><div class="number mock"><small id="mock-label">仅本页候选挂入的模拟人数</small><strong id="mock-count">—</strong><span id="mock-target" class="muted"></span></div></div></div></div><p class="muted">模拟假设只给ộ挂入一个新完整码：部分前缀人数按现有并集加本字、去重计算。前缀包含它不代表已唯一选定外二件。完整候选“1人”只是本字挂码，不是全库类型识别人数或效率证明。</p></section><section><h2>2. 四个位的具体比较</h2><div class="scroll"><table><thead><tr><th>路径</th><th>前置逐位含义</th><th>后置</th><th>实际状态</th></tr></thead><tbody><tr><td><code>iots</code></td><td>i圆主体桶 → o圆主体 → t一个外点 → s该点在主体下方</td><td><code>otsi</code></td><td>现行5人，ộ第5位</td></tr><tr><td><code>ioyw</code></td><td>i圆主体桶 → o圆主体 → y一个外线状构件 → w该构件在主体上方</td><td><code>oywi</code></td><td>现行46人，ộ第46位</td></tr><tr><td><code>iokl</code></td><td>i圆主体桶 → o圆主体 → k组相关入口、范围尚未定 → l新分支才选“外二件：折线＋点”</td><td><code>okli</code></td><td><strong>未批准；现行0。仅挂ộ的模拟1。</strong></td></tr></tbody></table></div><p>新分支的第三、第四位最终共同引用同一个外附件组；成员只引用既有折线和点，主体排除。折角有两段线仍只算一件；要求主体和两附件互相分离，取<strong>全部</strong>外附件，不能从三件中任挑两件。Q/ρ相接尾笔不在本分支范围。</p><div class="notice">这属于受限的B′：C/D合起来才确定对象域，<strong>不是严格A“到第三位就固定二件外组”</strong>。如果仍要求C单独唯一选对象、每个D字母只有一种全局意义，这个候选不满足，不能靠改标签掩盖。</div><details><summary>旧k路径如何保留，为什么不再加数量／排列码？</summary><p>现行<code>iokb</code>仍数原全字组2件，ô/ọ是主体＋1附件；<code>iokt</code>仍数原全字组3件。不能把它们叫外2件。iok前缀会混合旧全字组与新条件分支，显示时需要说明对象域。</p><p>本次只申请ộ的iokl，不申请ioko数量入口、iokg排列入口，也不批准8的方案2或其它C/D新义。既有iots/ioyw仍可看点、折线的上下位置；不让组合类型码再隐含未批准的排列条件。</p><p>其它C下的l继续原“左上斜”；新k/l不能同时装“全字组左上斜”。现在字符串空缺只表示无当前候选，不表示语义空位或零成本。</p></details></section><section><h2>3. 现行单附件入口可真实点选</h2><p>这些按钮才调用当前服务。它们仍以圆主体起手，不能冒称独立附件起手。模拟iokl不提供实际查询按钮。</p><div class="controls">${d.paths.filter(p=>p.kind!=='candidate').flatMap(p=>['front','back'].map(order=>`<button data-real="${order==='front'?p.canonical:p.back}" data-back="${order==='back'}">真实试查 ${order==='front'?p.canonical:p.back}</button>`)).join('')}</div><p id="real-status" class="status" role="status"></p><div id="real-candidates" class="candidate-grid"></div></section><section><h2>4. 仅一个新的具体取舍</h2><p><strong>是否接受只给ộ增加iokl/okli，并明确批准k/l的新条件义？</strong> 它一次表达外二件折线＋点，但要放弃“D/l在所有C下都只有左上斜这一义”的更强要求。</p><label class="choice"><input type="radio" name="decision" value="accept-minimal-iokl">接受这个最小本字候选及上述k/l换义<p class="muted">仅增加iokl，9→10路；原9路和epki首选不动。不连带批准数量码、排列码、其它字符或其它条件字典。</p></label><label class="choice"><input type="radio" name="decision" value="keep-current-entries">暂不增加组合码，继续用现有入口<p class="muted">保持9路和现有末位解释；可继续iots/ioyw及原路，但“数量2＋类型组合”的一条完整码暂未实现。</p></label><label>补充（选填，不能定可先不选）<textarea id="note" rows="3" placeholder="只写这个具体取舍；自然思路和24字不用重答"></textarea></label><div class="controls"><button id="copy">复制本处答复</button><button id="download">下载JSON</button></div><p id="decision-status" class="status" role="status"></p><textarea id="fallback" rows="7" readonly hidden aria-label="可手动复制的本处答复"></textarea><p class="muted">默认不选；独立草稿，不写人工审议。是否接受仍由总控核实，页面选择不会自动启用本候选。</p></section><section><h2>范围与状态</h2><p>只给本字挂码的模拟0→1，七例谓词命中1和全库规则推广人数是三个不同口径；最后一个仍未知。未加数量/排列码、不改首选，不注册新三码，也不把前后置算两路。</p><p>现行版本${esc(d.runtime)}＋${esc(d.shapeBoundary)}＋${esc(d.holeGroup)}。快照${esc(new Date(d.capturedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}))}。8已接受方向看孔组、位置/尺寸看单孔，不构成对本新D义的接受。</p><p>本次仅独立材料和专用静态页，未写公共确认源/运行逻辑、未重启服务。圆主体遗留、类型推广、正式词典与集成仍未完成。</p></section>`;
let route=2,back=false,step=0;const rect=(b,color)=>`<rect x="${b[0]}" y="${b[1]}" width="${b[2]-b[0]}" height="${b[3]-b[1]}" fill="${color}" fill-opacity=".08" stroke="${color}" stroke-width=".8"/>`;
function render(){const p=d.paths[route],candidate=p.kind==='candidate',code=back?p.back:p.canonical,steps=back?p.backSteps:p.frontSteps;document.querySelector('#typed').value=code.slice(0,step);document.querySelector('#mode-label').textContent=candidate?'本页模拟，候选未批准，不发送实际查询':'现行入口的只读分步说明';document.querySelector('#keycaps').innerHTML=[...code].map((letter,i)=>`<div class="keycap ${i<step?'pressed':''} ${i===step-1?'current':''}">${letter}<small>${back?'后置':'规范'}第${i+1}键</small></div>`).join('');document.querySelector('#next-key').disabled=step===4;document.querySelector('#previous-key').disabled=step===0;let boxes=rect(d.subjectBBox,'#2871a6');const objectChosen=candidate?(back?step>=3:step>=4):(back?step>=2:step>=3);if(objectChosen){if(candidate){for(const x of d.objects)boxes+=rect(x.object.bbox,'#af6520')}else boxes+=rect(p.object.bbox,'#af6520')}document.querySelector('#object-boxes').innerHTML=boxes;document.querySelector('#object-scope').textContent=candidate?(objectChosen?'橙框两成员＝同一外二件组；圆主体不计入。':'尚未确定外二件组；尤其iok不能这样命名。'):(objectChosen?'橙框只选该单附件；不是整个附件组。':'先认圆主体，再选一个附件。');if(!step){document.querySelector('#step-box').textContent='按“下一键”开始。或逐键输入本条码。';document.querySelector('#current-count').textContent='—';document.querySelector('#mock-count').textContent='—';document.querySelector('#current-target').textContent='';document.querySelector('#mock-target').textContent='';return}const s=steps[step-1];let extra='';if(candidate&&!back&&step===3)extra='<p class="error"><strong>当前iok不含ộ，且未固定外二件。</strong> 模拟加入完整iokl后，前缀并集才会多出本字；这不等于第三位已唯一选组。</p>';if(candidate&&objectChosen)extra+='<p class="error"><strong>新k/l分支：</strong>l表示外二件折线＋点，不表示原左上斜，也不编码上/下排列；尚未批准。</p>';if(back)extra+=`<p class="muted">本键对应规范第${s.normalizedPosition}位。${step===4?'最后i是桶，不是附件属性。':step===3?'此时l是规范末位属性，桶i尚未补上。':''}</p>`;document.querySelector('#step-box').innerHTML=`<strong>已输入 <code>${esc(s.prefix)}</code></strong><p>${esc(s.meaning)}</p>${extra}`;document.querySelector('#current-count').textContent=s.currentCount;document.querySelector('#current-target').textContent=s.targetCurrentlyReached?'现行前缀中有ộ':'现行前缀中没有ộ';document.querySelector('#mock-label').textContent=candidate?'仅给ộ挂入iokl的条件模拟':'不增加任何码，现行结果';document.querySelector('#mock-count').textContent=candidate?s.singleTargetMockCount:s.currentCount;document.querySelector('#mock-target').textContent=candidate?(step===4?'仅本字模拟候选ộ；现行仍为0，不是全库推广人数。':'只按未来完整码回填前缀并集，不表示对象域已固定。'):'与现行一致，真实点选在下方。'}
document.querySelector('#route').onchange=e=>{route=Number(e.target.value);step=0;document.querySelector('#input-status').textContent='';render()};document.querySelector('#order').onchange=e=>{back=e.target.value==='back';step=0;document.querySelector('#input-status').textContent='';render()};document.querySelector('#next-key').onclick=()=>{step=Math.min(4,step+1);document.querySelector('#input-status').textContent='';render()};document.querySelector('#previous-key').onclick=()=>{step=Math.max(0,step-1);render()};document.querySelector('#reset').onclick=()=>{step=0;render()};document.querySelector('#typed').oninput=e=>{const v=e.target.value.trim().toLowerCase(),p=d.paths[route],code=back?p.back:p.canonical;if(!code.startsWith(v)||!/^[a-z]{0,4}$/.test(v)){document.querySelector('#input-status').textContent='本处只演示所选码的前缀，不执行实际查询。';return}step=v.length;document.querySelector('#input-status').textContent='';render()};render();
let token=0;h.querySelectorAll('[data-real]').forEach(btn=>btn.onclick=async()=>{const t=++token,code=btn.dataset.real,isBack=btn.dataset.back==='true',st=document.querySelector('#real-status'),grid=document.querySelector('#real-candidates');st.textContent='读取当前'+code+'…';grid.replaceChildren();try{const params=new URLSearchParams({allocation:'1',prefix:code});if(isBack){params.set('order','back');params.set('routeLength','4')}const r=await fetch('/api/shape-overview/query?'+params);if(!r.ok)throw Error('HTTP '+r.status);const q=await r.json();if(t!==token)return;st.textContent=`${code}当前${q.total}候选，点击ộ。`;for(const [i,row] of q.rows.entries()){const b=document.createElement('button'),img=document.createElement('span'),label=document.createElement('span');b.className='candidate';img.className='sprite';img.setAttribute('role','img');img.setAttribute('aria-label',row.char);if(row.preview){img.style.backgroundImage=`url("/${row.preview.url}")`;img.style.backgroundPosition=`-${row.preview.x}px -${row.preview.y}px`}else img.textContent=row.char;label.textContent='U+'+row.cp.toString(16).toUpperCase();b.append(img,label);b.onclick=()=>{if(row.cp===7897){b.classList.add('found');st.textContent=`已找到ộ：${code}，${q.total}人，第${i+1}位；仍先圆主体后单附件。`}else st.textContent='不是目标ộ，可继续点选。'};grid.append(b)}}catch(e){if(t===token)st.textContent='现行服务读取失败：'+e.message+'；模拟不表示实际入口。'}});
const storageKey='minimal-iokl-decision-20261027-v1',draft={schema:'minimal-iokl-decision-20261027-v1',decision:'',note:''};try{const old=JSON.parse(localStorage.getItem(storageKey)||'null');if(old?.schema===draft.schema)for(const k of ['decision','note'])if(typeof old[k]==='string')draft[k]=old[k]}catch{}const save=()=>{draft.updatedAt=new Date().toISOString();try{localStorage.setItem(storageKey,JSON.stringify(draft));document.querySelector('#decision-status').textContent='独立答复草稿已保存；实际确认和码表未变。'}catch{document.querySelector('#decision-status').textContent='浏览器保存失败，请复制或下载本处答复。'}};h.querySelectorAll('input[name=decision]').forEach(el=>{el.checked=el.value===draft.decision;el.onchange=()=>{draft.decision=el.value;save()}});document.querySelector('#note').value=draft.note;document.querySelector('#note').oninput=e=>{draft.note=e.target.value;save()};const text=()=>JSON.stringify({...draft,evidenceCapturedAt:d.capturedAt,scope:'仅ộ新增iokl/okli及明示k/l对象域/末l换义，保留原9路及epki；不含数量/排列/其它字',status:'供总控核实的一项具体取舍；未自动写入人工审议或启用候选',exportedAt:new Date().toISOString()},null,2);document.querySelector('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(text());document.querySelector('#decision-status').textContent='已复制，可交回当前总控。'}catch{const el=document.querySelector('#fallback');el.hidden=false;el.value=text();el.focus();el.select();document.querySelector('#decision-status').textContent='请手动复制或下载JSON。'}};document.querySelector('#download').onclick=()=>{const u=URL.createObjectURL(new Blob([text()],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='ộ最小iokl取舍.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
}main().catch(e=>{document.querySelector('#main').textContent='按键演示读取失败：'+e.message+'；原有审核、草稿和运行码未变。'});})();
